// The agent's keys (Agent-Protocol.md sections 3 and 5). PROTOTYPE. Agent-only: a host page must never import this.
//
// A NEW identity is generated here (first cut: fresh material only, never an imported or rebuilt older seed):
//   - a random identity seed -> the .me identity (identityHash, its own key), used ONCE to sign the registration
//     statement, then dropped: this identity never has a seed in any page, and no v1 authority survives the agent;
//   - a random Ed25519 AGENT key, generated by WebCrypto as non-extractable and kept in this origin's IndexedDB.
// Every later proof is signed with the agent key. Nothing here leaves the agent except public keys and signatures.
//
// Not in this cut (stated): an unlock secret over the stored key (it is protected by the origin and the device only),
// lock, recovery, rotation, several devices.
import MeKernel from 'this.me';
import { PROOF_V2, base64urlBytes, buildV2Bytes, newRequestId, type V2Fields, type V2RegisterFields } from './protocol';

const DB = 'me-agent';
const STORE = 'identities';

export type AgentIdentity = {
  identityHash: string;
  namespace: string;
  keyId: string;
  /** Agent public key, JWK `x` (base64url). */
  agentKey: string;
  privateKey: CryptoKey;
  createdAt: number;
};

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB, 1);
    req.onupgradeneeded = () => req.result.createObjectStore(STORE, { keyPath: 'identityHash' });
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function put(identity: AgentIdentity): Promise<void> {
  const db = await openDb();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).put(identity);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
  db.close();
}

export async function listIdentities(namespace?: string): Promise<AgentIdentity[]> {
  const db = await openDb();
  const all = await new Promise<AgentIdentity[]>((resolve, reject) => {
    const req = db.transaction(STORE, 'readonly').objectStore(STORE).getAll();
    req.onsuccess = () => resolve(req.result as AgentIdentity[]);
    req.onerror = () => reject(req.error);
  });
  db.close();
  return namespace ? all.filter((i) => i.namespace === namespace) : all;
}

async function keyIdOf(agentKey: string): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`me-agent-key:${agentKey}`)));
  return Array.from(digest.slice(0, 16), (b) => b.toString(16).padStart(2, '0')).join('');
}

export async function signV2(identity: AgentIdentity, fields: V2Fields): Promise<{ bytes: string; signature: string }> {
  const bytes = buildV2Bytes(fields);
  const sig = new Uint8Array(await crypto.subtle.sign({ name: 'Ed25519' }, identity.privateKey, new TextEncoder().encode(bytes)));
  return { bytes, signature: base64urlBytes(sig) };
}

export type RegistrationBody = {
  /** The v2 registration statement, signed by the agent key. */
  statement: { bytes: string; signature: string };
  /** The new identity's own (v1-format) proof over the same statement: it binds the identityHash to the agent key. */
  identityProof: { identityHash: string; publicKey: string; message: string; signature: string };
};

/**
 * Generates a new identity and its agent key here, and returns the registration to send. The identity is stored only
 * after the server accepted the registration (storePending), so a refused registration leaves nothing behind.
 */
export async function createIdentity(input: { namespace: string; audience: string; origin: string; handle?: string; ttlMs?: number }): Promise<{ identity: AgentIdentity; body: RegistrationBody }> {
  const seedBytes = new Uint8Array(32);
  crypto.getRandomValues(seedBytes);
  const me = new (MeKernel as any)(Array.from(seedBytes, (b) => b.toString(16).padStart(2, '0')).join(''));
  seedBytes.fill(0);
  // The identity's name (its `@` expression): prove() needs one. Given, or random for a test identity.
  const handle = input.handle && /^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/.test(input.handle) ? input.handle : `id${newRequestId().slice(0, 10)}`;
  me['@'](handle);

  const pair = (await crypto.subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify'])) as CryptoKeyPair;
  const agentKey = String(((await crypto.subtle.exportKey('jwk', pair.publicKey)) as JsonWebKey).x || '');
  const keyId = await keyIdOf(agentKey);

  // The identity's hash comes from its own first proof; sign a placeholder to learn it, then the real statement.
  const runtime = me['!'];
  const prove = (challenge: string) => runtime.prove({ rootNamespace: input.namespace, challenge });
  const probe = await prove('{}');
  const identityHash = String(probe.identityHash || '');
  if (!identityHash) throw new Error('IDENTITY_UNAVAILABLE');

  const issuedAt = Date.now();
  const fields: V2RegisterFields = {
    v: PROOF_V2, op: 'register', identityHash, namespace: input.namespace, keyId, agentKey,
    nonce: newRequestId(), issuedAt, expiresAt: issuedAt + (input.ttlMs ?? 60_000), origin: input.origin, audience: input.audience,
  };
  const identity: AgentIdentity = { identityHash, namespace: input.namespace, keyId, agentKey, privateKey: pair.privateKey, createdAt: issuedAt };
  const statement = await signV2(identity, fields);
  const proof = await prove(statement.bytes);
  // The seed lived only in `me`; nothing keeps it after this function returns.
  return {
    identity,
    body: {
      statement,
      identityProof: { identityHash: String(proof.identityHash), publicKey: String(proof.publicKey), message: String(proof.message), signature: String(proof.signature) },
    },
  };
}

export const storeIdentity = put;
